WITH state(kind, k1, k2, k3) AS (SELECT 'schema', name, type, sql FROM sqlite_schema WHERE name IN ('t1','t2','t3') UNION ALL SELECT 'stat', tbl, coalesce(idx,'<null>'), stat FROM sqlite_stat1 UNION ALL SELECT 't1', quote(a), quote(b), '' FROM t1 UNION ALL SELECT 't2', quote(c), quote(d), '' FROM t2 UNION ALL SELECT 't3', quote(e), quote(f), '' FROM t3) SELECT kind, k1, k2, k3 FROM state ORDER BY kind, k1, k2, k3;